from collections import Counter
from typing import Iterable

from .models import Discrepancy, Row


def find_discrepancies(left_rows: Iterable[Row], right_rows: Iterable[Row]) -> list[Discrepancy]:
    left_list = list(left_rows)
    right_list = list(right_rows)

    left_counter = Counter((r.merchant_order_id, r.provider_txn_id) for r in left_list)
    right_counter = Counter((r.merchant_order_id, r.provider_txn_id) for r in right_list)

    discrepancies: list[Discrepancy] = []

    # Detect duplicates on left
    for key, count in left_counter.items():
        if count > 1:
            discrepancies.append(Discrepancy(
                kind="duplicate_left",
                merchant_order_id=key[0],
                provider_txn_id=key[1],
                detail=f"appears {count} times on left"
            ))

    # Get unique keys
    left_keys = set(left_counter.keys())
    right_keys = set(right_counter.keys())

    # Build maps for single entries (first occurrence)
    left_map = {}
    for r in left_list:
        key = (r.merchant_order_id, r.provider_txn_id)
        if key not in left_map:
            left_map[key] = r

    right_map = {}
    for r in right_list:
        key = (r.merchant_order_id, r.provider_txn_id)
        if key not in right_map:
            right_map[key] = r

    # Check for amount mismatches and missing records
    for key in left_keys:
        if key in right_keys:
            # Both exist - check amount mismatch
            if left_map[key].amount_cents != right_map[key].amount_cents:
                discrepancies.append(Discrepancy(
                    kind="amount_mismatch",
                    merchant_order_id=key[0],
                    provider_txn_id=key[1],
                    detail=f"left={left_map[key].amount_cents}, right={right_map[key].amount_cents}"
                ))
        else:
            # Missing on right
            discrepancies.append(Discrepancy(
                kind="missing_right",
                merchant_order_id=key[0],
                provider_txn_id=key[1],
                detail="present on left but not on right"
            ))

    for key in right_keys:
        if key not in left_keys:
            # Missing on left
            discrepancies.append(Discrepancy(
                kind="missing_left",
                merchant_order_id=key[0],
                provider_txn_id=key[1],
                detail="present on right but not on left"
            ))

    return discrepancies
